package generated;

import com.openjiuwen.core.foundation.tool.Tool;
import java.util.LinkedHashMap;
import java.util.Map;

public final class AccountBalanceTool extends Tool {

  private static final String INPUT_INVALID = "TOOL_INPUT_CONTRACT_INVALID";
  private static final String RESPONSE_INVALID = "TOOL_RESPONSE_CONTRACT_INVALID";

  private final Tool transport;

  public AccountBalanceTool(Tool transport) {
    super(transport.getCard());
    this.transport = transport;
  }

  @Override
  protected Object invokeInternal(Map<String, Object> inputs, Map<String, Object> kwargs) throws Exception {
    validateInput(inputs);

    Object response = transport.invoke(inputs, kwargs);

    if (!(response instanceof Map)) {
      throw new IllegalStateException(RESPONSE_INVALID);
    }
    Map<?, ?> fields = (Map<?, ?>) response;
    Object accountId = fields.get("accountId");
    Object currency = fields.get("currency");
    Object availableBalanceFen = fields.get("availableBalanceFen");
    Object asOf = fields.get("asOf");

    if (!(accountId instanceof String)
        || !(currency instanceof String)
        || !(asOf instanceof String)
        || !(availableBalanceFen instanceof Integer || availableBalanceFen instanceof Long)) {
      throw new IllegalStateException(RESPONSE_INVALID);
    }

    Map<String, Object> result = new LinkedHashMap<>();
    result.put("accountId", accountId);
    result.put("currency", currency);
    result.put("availableBalanceFen", availableBalanceFen);
    result.put("asOf", asOf);
    return result;
  }

  private static void validateInput(Map<String, Object> inputs) {
    if (inputs == null || inputs.size() != 1 || !inputs.containsKey("accountId")) {
      throw new IllegalArgumentException(INPUT_INVALID);
    }
    Object accountId = inputs.get("accountId");
    if (!(accountId instanceof String) || ((String) accountId).trim().isEmpty()) {
      throw new IllegalArgumentException(INPUT_INVALID);
    }
  }
}
